    """Return the set of nodes that are blocked due to transitive failures.

    A node is blocked if any of its direct or indirect dependencies is in the
    failed set. The failed nodes themselves are not considered blocked.
    """
    blocked = set()
    # Perform a reverse traversal: for each failed node, mark its dependents
    # and propagate.
    # Build reverse adjacency list
    rev = {node: [] for node in graph}
    for node, deps in graph.items():
        for dep in deps:
            rev[dep].append(node)
    stack = list(failed)
    while stack:
        cur = stack.pop()
        for dependent in rev.get(cur, []):
            if dependent not in failed and dependent not in blocked:
                blocked.add(dependent)
                stack.append(dependent)
    return blocked


def classify(graph, sequence, statuses):
    """Classify nodes into ready, blocked, running, done, failed.

    * ``graph`` – dict mapping node id to list of its direct dependencies.
    * ``sequence`` – topological ordering of all nodes (canonical).
    * ``statuses`` – mapping node id to one of "pending", "running", "done",
      "failed". Missing entries are treated as "pending".

    The function validates input, computes transitive blocking caused by any
    failed node, and then walks the canonical sequence to produce ordered
    lists for each category. Nodes that are pending but have all direct
    dependencies marked as "done" are considered "ready". Nodes that are
    pending and have any dependency that is "failed" (directly or indirectly)
    are "blocked". Explicit statuses (running, done, failed) take precedence
    over derived blocked status.
